-- Schema for the birthday tracker. Runs once, when the Postgres data volume is first created
-- (mounted into /docker-entrypoint-initdb.d by docker-compose.yml).

CREATE TABLE IF NOT EXISTS birthdays (
    -- UUIDv7 generated by the Backend API and carried in the submission message, so a redelivered
    -- message can be written with INSERT ... ON CONFLICT (id) DO NOTHING (idempotent consumer).
    -- v7 is time-ordered, which keeps the primary key index append-mostly.
    id                    UUID        PRIMARY KEY,
    -- Field values (non-blank name, past birth_date, 1–14 day window, valid email) are validated
    -- by the Backend API before a submission is published; the database only enforces types and NOT NULL.
    name                  VARCHAR(200) NOT NULL,
    birth_date            DATE        NOT NULL,
    -- Days before the birthday to send a reminder (1–14), chosen in the UI.
    reminder_window_days  SMALLINT    NOT NULL,
    -- Who the email team's service should send the reminder to; included in each reminder message.
    -- Nullable for now, until the UI collects it.
    reminder_email        VARCHAR(200),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS birthdays_name_idx ON birthdays (lower(name));
CREATE INDEX IF NOT EXISTS birthdays_created_at_idx ON birthdays (created_at DESC);
